import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import streamlit as st
from sklearn.metrics import confusion_matrix, roc_curve, roc_auc_score
from .common import find_column, first_value, styled_figure


def render_validation(data):
    st.subheader("Validation analysis")
    is_oof = data["metrics"].get("evaluation_method") == "out_of_fold"
    predictions = data["frames"]["validation_predictions.csv"]
    metrics = data["metrics"]

    if is_oof:
        st.subheader("Out-of-Fold Validation Analysis")
        st.caption(
            "Each prediction was generated by a model that "
            "did not train on that sample (out-of-fold prediction)."
        )
    else:
        st.subheader("Holdout Validation Analysis")
        st.caption(
            "Predictions were generated by a model trained on "
            "the training split and evaluated on the held-out split."
        )

    if predictions is None or predictions.empty:
        st.warning("Validation predictions are empty.")
        return

    actual_col = find_column(predictions, ["Actual", "y_true", "actual", "survived", "target"])
    predicted_col = find_column(predictions, ["Predicted", "y_pred", "prediction", "predicted_label"])
    prob_col = find_column(predictions, ["Probability", "probability", "prob", "survival_probability", "y_probability"])
    threshold = first_value(metrics, "decision_threshold", "threshold", default=0.5)

    left, right = st.columns(2)
    with left:
        st.markdown("#### Confusion matrix")
        matrix = metrics.get("confusion_matrix")
        if matrix is None and actual_col and predicted_col:
            matrix = confusion_matrix(predictions[actual_col], predictions[predicted_col], labels=[0, 1]).tolist()
        if matrix is not None:
            matrix = np.asarray(matrix)
            if matrix.shape == (2, 2):
                fig, ax = plt.subplots(figsize=(5.2, 4.3))
                im = ax.imshow(matrix, cmap="Blues")
                ax.set_xticks([0, 1], labels=["Did not survive", "Survived"])
                ax.set_yticks([0, 1], labels=["Did not survive", "Survived"])
                ax.set_xlabel("Predicted label")
                ax.set_ylabel("Actual label")
                ax.set_title("Confusion matrix")
                cutoff = matrix.max() / 2 if matrix.size else 0
                for i in range(2):
                    for j in range(2):
                        ax.text(j, i, f"{int(matrix[i, j])}", ha="center", va="center", color="white" if matrix[i, j] > cutoff else "#152536", fontsize=13, fontweight="bold")
                fig.colorbar(im, ax=ax, fraction=.046, pad=.04)
                styled_figure(fig)
                tn, fp, fn, tp = matrix.ravel()
                st.caption(f"TN: {tn} · FP: {fp} · FN: {fn} · TP: {tp}")
            else:
                st.warning("confusion_matrix must be a 2×2 matrix for binary classification.")
        else:
            st.warning("No confusion matrix found in metrics JSON, and actual/predicted labels are unavailable.")

    with right:
        st.markdown("#### ROC curve")
        if actual_col and prob_col and predictions[actual_col].nunique(dropna=True) == 2:
            y_true = predictions[actual_col].astype(int)
            y_prob = predictions[prob_col].astype(float)
            fpr, tpr, _ = roc_curve(y_true, y_prob)
            auc = roc_auc_score(y_true, y_prob)
            fig, ax = plt.subplots(figsize=(5.2, 4.3))
            ax.plot(fpr, tpr, linewidth=2.4, label=f"Model (AUC = {auc:.3f})")
            ax.plot([0, 1], [0, 1], linestyle="--", color="gray", label="Random baseline")
            ax.set(xlabel="False Positive Rate", ylabel="True Positive Rate", title="ROC curve", xlim=(0, 1), ylim=(0, 1.02))
            ax.grid(True, alpha=.25)
            ax.legend(frameon=False, loc="lower right")
            styled_figure(fig)
        else:
            st.info("ROC curve requires both actual labels and probability scores, with both classes present in the validation split.")

    st.divider()
    st.markdown("#### Prediction explorer")
    view = predictions.copy()
    if actual_col and predicted_col:
        view["_is_error"] = view[actual_col].astype(str) != view[predicted_col].astype(str)
        filter_choice = st.selectbox("Show predictions", ["All rows", "Incorrect predictions only", "Correct predictions only"])
        if filter_choice == "Incorrect predictions only":
            view = view[view["_is_error"]]
        elif filter_choice == "Correct predictions only":
            view = view[~view["_is_error"]]
    if prob_col:
        view["_near_threshold"] = (pd.to_numeric(view[prob_col], errors="coerce") - float(threshold)).abs() <= 0.10
        show_uncertain = st.checkbox("Only show probabilities within ±0.10 of the decision threshold", value=False)
        if show_uncertain:
            view = view[view["_near_threshold"]]
    display_cols = [c for c in view.columns if not c.startswith("_")]
    st.caption(f"Showing {len(view):,} of {len(predictions):,} validation rows · threshold = {float(threshold):.2f}")
    st.dataframe(view[display_cols], use_container_width=True, hide_index=True)
    st.download_button("Download displayed predictions", view[display_cols].to_csv(index=False).encode("utf-8"), "validation_predictions_filtered.csv", "text/csv")
